import { TableConfig } from "@/store/dictionary";
import ajax from "@code/utils/ajax";
import { Button, Space, Table, TableColumnProps, Tooltip, Drawer, Radio, Checkbox } from "@arco-design/web-react";
import { IconQuestionCircle } from "@arco-design/web-react/icon";
import React, { useEffect, useMemo, useState } from "react";

interface DictionaryTableProps {
    table: TableConfig
}

const structureColumns: TableColumnProps[] = [
    { title: "数据表字段", dataIndex: "key" },
    { title: "字段类型", dataIndex: "type" },
    { title: "字段长度", dataIndex: "length" },
    { title: "是否可为空", dataIndex: "nullable",
        render: (col) => <Checkbox checked={col} />    
    },
    {
        title: "默认值", dataIndex: "default"
    },
    { title: "字段描述", dataIndex: "desc" },
    { title: "字段备注", dataIndex: "comment", 
        render(col, item, index) {
            if(col) return (
                <Tooltip content={<div className="whitespace-pre-wrap">{col}</div>}>
                    <IconQuestionCircle />
                </Tooltip>
            )
            return null;
        },
    },
]

const DictionaryTable = ({ table }: DictionaryTableProps) => {


    // 当前查看类型
    const [type, setType] = useState<'structure' | 'data'>('structure');
    const [total, setTotal] = useState(0);
    const [current, setCurrent] = useState(1);
    const [pageSize, setPageSize] = useState(50);
    const [loading, setLoading] = useState(false);
    const [data, setData] = useState([]);

    const columns = useMemo(() => {

        return table.column.filter((o) => o.key != 'tenant').map((o) => {

            return {
                // className: "whitespace-nowrap",
                width: 60 + (`${o.desc}`.length) * 14,
                title: (
                    <Space>
                        <span>{o.desc}({o.key})</span>
                        {o.comment? (
                            <Tooltip content={<div className="whitespace-pre-wrap">{o.comment}</div>}>
                                <IconQuestionCircle />
                            </Tooltip>
                        ): null}
                    </Space>
                ),
                dataIndex: o.key
            } as TableColumnProps;
        })
    },[table])

    useEffect(() => {
        if(type == 'data'){
            setLoading(true)
            ajax.post('/apijson/gets', {
                [`${table.tableName}[]`]: {
                    "query": 2,
                    count: pageSize,
                    page: current,
                    [`${table.tableName}`]: {

                    }
                },
                "info@": `/${table.tableName}[]/info`,
            }).then((res) => {
                setData(res[table.tableName])
                setTotal(res.info.total)
            }).finally(() => {
                setLoading(false)
            })
        }
    },[type, current, pageSize])

    return (
        <div className="h-full flex flex-col p-4">
            <div className="flex items-center justify-between pb-2">
                {table.tableName}({table.desc})
                <Space>
                    <Radio.Group
                        type='button'
                        options={[
                            { value: "structure", label: "数据结构" },
                            { value: "data", label: "查看数据" },
                        ]}
                        value={type}
                        onChange={(v) => setType(v)}
                    />
                </Space>
            </div>
            {type == 'structure'? (
                <Table
                    tableLayoutFixed
                    columns={structureColumns}
                    data={table.column.filter((o) => o.key != 'tenant')}
                    pagination={false}
                />
            ): (
                <Table
                    columns={columns}
                    data={data}
                    loading={loading}
                    scroll={{
                        x: true,
                        y: '60vh',
                    }}
                    pagination={{
                        current: current,
                        pageSize: pageSize,
                        showTotal: true,
                        sizeCanChange: true,
                        sizeOptions:[10,20,50, 100],
                        total: total,
                        onPageSizeChange(size, current) {
                            setPageSize(size)
                            setCurrent(current);
                        },
                    }}
                />
            )}
        </div>
    )
}


export default DictionaryTable